window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n    <div class=\"stack\">\n      <div class=\"eyebrow\">Self-test for couples · three roles · 15 minutes</div>\n      <h1>The Rose of Love</h1>\n      <p class=\"lead\">In a relationship, a man lives in three roles: lover, husband, father. A woman lives in three roles too: lover, wife, mother. Each role nourishes one of the components of love. Harmony appears when all three are alive.</p>\n    </div>\n    <div class=\"roles\">\n      <div class=\"role r0\"><b>Lover</b><span>Attraction, passion</span></div>\n      <div class=\"role r1\"><b>Husband · Wife</b><span>Closeness, trust</span></div>\n      <div class=\"role r2\"><b>Father · Mother</b><span>Commitment, support</span></div>\n    </div>\n    <div class=\"card stack\">\n      <h3>How it works</h3>\n      <p>There are no questions about feelings here, only about actions. Your partner does not see our intentions, they see what we do. Think back over the last 4 weeks and mark how often each thing really happened.</p>\n      <p>Two parts of 30 items each. <b>Part 1:</b> what you do. <b>Part 2:</b> how your partner shows up for you. At the end you will get a detailed report: a portrait of the woman, a portrait of the man, your couple’s triangle, recommendations and questions to reflect on. You can get the report as a PDF.</p>\n      <div class=\"scale-legend\"><span><b>0</b> never</span><span><b>1</b> 1–2 times</span><span><b>2</b> sometimes</span><span><b>3</b> often</span><span><b>4</b> almost always</span></div>\n      <p class=\"note\">If you have no children, apply the items about children to your home, your loved ones and your shared future.</p>\n    </div>\n    <div data-testinfo></div>\n    <div class=\"stack\">\n      <h3>What are your names?</h3>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"nameMe\">Your name</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"For example, Anna\"></div>\n        <div class=\"field\"><label for=\"nameP\">Your partner’s name</label><input id=\"nameP\" maxlength=\"30\" placeholder=\"For example, Michael\"></div>\n      </div>\n      <p class=\"note\">Your names are only used to make your report personal.</p>\n    </div>\n    <div class=\"stack\">\n      <h3>Who is taking the test?</h3>\n      <div class=\"choices\">\n        <button class=\"choice\" id=\"pick-f\" data-g=\"f\"><b>I am a woman</b><span>Lover, wife, mother</span></button>\n        <button class=\"choice\" id=\"pick-m\" data-g=\"m\"><b>I am a man</b><span>Lover, husband, father</span></button>\n      </div>\n    </div>\n    <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\">Step 1 of 6</span>\n        <span class=\"eyebrow\" id=\"countLabel\">0 of 60</span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Back</button>\n      <button class=\"btn\" id=\"next\" disabled>Next</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = 'https://script.google.com/macros/s/AKfycbyizp1XjzNdrUj4WHgj4Vyj81QhjY2D7puqyeY3LaweWB4mePxPhfHCx5fIsfaJy9hV/exec';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://irynawiederkehr-cmd.github.io/tests/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n", "const BRAND = 'psy';\nconst TEST_META = { id: 'roza-lyubvi', name: 'The Rose of Love' };\nconst TEST_INFO = {\n  why: 'I created this questionnaire to help couples see their relationship not through hurt and expectations, but through concrete actions. Often both partners love each other, but each reads love in their own language. The questionnaire translates feelings into the language of actions and shows where love is alive in your couple and where it has gone quiet.',\n  gives: [\n    'You will see which of the three roles you live out brightly, and which are still quiet.',\n    'You will compare what you put into the relationship and what you receive from your partner.',\n    'You will find out your couple’s type according to Robert Sternberg’s triangular theory of love.',\n    'You will get a plan of small steps for 4 weeks and questions to talk about as a couple.'\n  ],\n  next: [\n    'Don’t rush to conclusions: the result is a snapshot of the last 4 weeks, not a verdict on your relationship.',\n    'Choose one action from the plan and do it for at least a week.',\n    'Invite your partner to take the test, and compare your triangles calmly, without blame.',\n    'In 4 weeks, take the test again and see what has changed.',\n    'If the conversation doesn’t work out or the topic brings up pain, discuss the result with a professional.'\n  ]\n};\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Iryna Voznesenskaya',\n  about: 'ICF coach in Switzerland and psychologist in Ukraine.',\n  coach: { place: 'Switzerland · Zurich', title: 'Coach', text: 'Transformational coach and neurocoach, ICF. I help Russian-speaking emigrants through adaptation: to find themselves and their place in a new world. In Switzerland I work only as a coach. Coaching is not psychotherapy and does not replace psychological or medical care.',\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Ukraine · Kyiv', title: 'Psychologist in Ukraine', text: 'I work with couple relationships: I help couples hear each other, bring back closeness and find balance. As a psychologist I only work with clients in Ukraine, based on my Ukrainian qualification.',\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'The Rose of Love', brand: 'psy', tag: 'For couples · 15 minutes',\n    text: 'Three roles in a couple: attraction, closeness and commitment. Find out which roles are vivid, which have gone quieter, and how you meet each other.' },\n  { id: 'kompas', path: 'kompas/', name: 'Adaptation Compass', brand: 'coach', tag: 'For yourself · 10 minutes',\n    text: 'Where you are now in emigration: six areas of your new life, your path between two cultures and your next small step.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram channel</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4><p>${p.text}</p><div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'About the author'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono\">IV</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return BRAND === 'coach' ? 'Iryna Voznesenskaya · ICF coach (Switzerland) · psychologist (Ukraine)' : 'Iryna Voznesenskaya · psychologist (Ukraine) · ICF coach (Switzerland)';\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'How did you hear about me?', opts: ['Instagram','Telegram','Recommended by friends or acquaintances','Google search','Facebook','Other'] },\n  interest: { q: 'What are you interested in?', opts: ['Psychology: couple relationships','Coaching: adapting to emigration and finding yourself','Just curious for now'] }\n};\nconst GREET = {\n  head: ['Hi! I’m {A}','Glad you’re here! My name is {A}','Welcome! I’m {A}','Hello! I’m {A}'],\n  about: ['ICF coach in Switzerland and psychologist in Ukraine.','I work in two countries: as an ICF coach in Switzerland and as a psychologist in Ukraine.','I help people find themselves and build warm relationships: as an ICF coach in Switzerland and as a psychologist in Ukraine.'],\n  ask: ['Before the test, please answer two short questions. This helps me understand how I can be useful to you.',\n        'Two short questions before we start, and then straight to the test.',\n        'It matters to me to know who comes to my tests. Please answer two short questions.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono\">IV</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} You can choose more than one option.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Go to the test</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, thank you for your honest answers.',\n           '{N}, you are already taking an important step: looking honestly at your relationship.',\n           '{N}, this report is only the beginning of a conversation.',\n           '{N}, the test shows a picture, but real change begins in conversation.',\n           '{N}, behind every number in this report is your own story.'],\n    body: ['The numbers show where things have gone quiet in your couple. But behind them there is always something personal: tiredness, hurt, habits, unspoken expectations. In our meeting we will gently look at your situation and find the first steps to {F}.',\n           'Sometimes one precise question is enough for a couple to hear each other again. If you would like to {F}, I invite you to a meeting: calm, gentle, without judgement.',\n           'Relationships change not through knowledge, but through new actions. I help couples find these actions and not give them up after a week. Let’s look together at how to {F}.',\n           'You can move towards change on your own, or with support. In our meeting we will discuss your triangle and outline how to {F}.',\n           'Many couples live with the same tension for years because they don’t know how to start the conversation. I will help you start it in a way that helps you {F}.'],\n    cta:  ['Book a 30-minute introductory meeting: we will discuss your result and decide whether further work on your relationship is needed.',\n           '30 minutes online. You talk, I listen and ask questions. After the meeting it will be clearer what is happening in your couple and where to start.',\n           'The first meeting lasts 30 minutes. That is enough to understand what you need and to map out how to work on your relationship.'],\n    title: ['I invite you to a 30-minute meeting','Let’s talk about your relationship','The next step is a conversation'],\n    legal: 'Psychologist consultations are held online for clients in Ukraine.'\n  },\n  coach: {\n    open: ['{N}, thank you for making time for yourself.',\n           '{N}, you are already taking an important step: looking at yourself honestly and gently.',\n           '{N}, this report is only the beginning of the journey.',\n           '{N}, sometimes one test opens up more questions than answers. And that is good.',\n           '{N}, everything you see now can be turned into support.'],\n    body: ['Emigration changes everything: language, habits, roles in the family and even how we see ourselves. In coaching we look for what supports you in the new world and, step by step, help you {F}.',\n           'When the country changes, we change too. Sometimes it feels like losing yourself. I help you find yourself again so that you can {F}.',\n           'You have already come a long way. Coaching helps you turn this experience into strength and {F}.',\n           'The answers are already within you, but they are hard to hear in the bustle of a new life. Working with me, you will find your own answers and decide how to {F}.',\n           'Adaptation is not only about documents and language. It is about finding your place. Let’s look together at how to {F}.'],\n    cta:  ['Book a 30-minute introductory meeting: we will talk about what you need and what working on yourself could look like.',\n           '30 minutes online. You tell me what matters to you right now, and I ask questions. After the meeting it will be clearer where to go next.',\n           'The first meeting lasts 30 minutes. That is enough to understand what you need and to map out the first steps.'],\n    title: ['I invite you to a 30-minute meeting','Let’s talk about you','The next step is a conversation'],\n    legal: 'Coaching is not psychotherapy and does not replace psychological or medical care.'\n  }\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'bring more warmth and understanding into your relationship', coach: 'find your place in the new world' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /^Coaching/.test(x) : /^Psycholog/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">You are also interested in my work as a ${AUTHOR[other].title.replace(/^./, c => c.toLowerCase())}. You can find out more about it here: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"eyebrow\">${key === 'psy' ? 'Working on your relationship' : 'Working on yourself'}</div>\n    <h2>${pick(P.title, 0)}</h2>\n    <p class=\"lead\"><b>${fill(pick(P.open, 1))}</b></p>\n    <p>${fill(pick(P.body, 2))}</p>\n    <div class=\"invite-cta\"><p>${fill(pick(P.cta, 3))}</p>\n      <p><b>How to book:</b> send me the word <b>“MEETING”</b>, and I will suggest a convenient time.</p>\n      <div class=\"invite-links\">${links.join('')}</div></div>\n    ${otherLine}\n    <p class=\"note\">${P.legal}</p></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Also try</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span>${t.text}</span><span class=\"tgo\">Take the test →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'This questionnaire is a tool for self-discovery and conversation. It is not a psychological or medical diagnosis or a psychotherapeutic assessment, and it does not replace a consultation with a professional.',\n  'The results reflect your personal perception over the last 4 weeks and may change.',\n  'If you are going through a crisis, violence or a threat to your safety, please contact a professional or the emergency services in your country.'\n];\n/* Точка А → точка Б: если в TEST_INFO есть from / to / key — показываем, с чем человек приходит и с чем уходит. */\nfunction abHtml(){\n  if (typeof TEST_INFO === 'undefined' || !TEST_INFO.from) return '';\n  const ps = a => [].concat(a).map(x => `<p>${x}</p>`).join('');\n  return `<div class=\"ab\"><div class=\"ab-a\"><span class=\"ab-l\">Point A · where you start</span>${ps(TEST_INFO.from)}</div>\n    <div class=\"ab-arrow\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 24\" width=\"40\" height=\"24\"><path d=\"M2 12h32M26 4l8 8-8 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>\n    <div class=\"ab-b\"><span class=\"ab-l\">Point B · what you leave with</span>${ps(TEST_INFO.to)}</div></div>\n    ${TEST_INFO.key ? `<div class=\"ab-key\"><b>The key insight</b><p>${TEST_INFO.key}</p></div>` : ''}`;\n}\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  if (TEST_INFO.from) return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Why take it</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>${abHtml()}\n    <div class=\"ti-cols\"><div><h3>What to do with it</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div></div></div>`;\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">About this questionnaire</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>What it gives you</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>What to do with it</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\n/* Текст «Важно» сверяется по смыслу с каждым тестом: свой вариант — TEST_DISCLAIMER в meta.js (null = общая строка). */\nfunction disclaimerHtml(list){\n  const D = list || (typeof TEST_DISCLAIMER !== 'undefined' ? TEST_DISCLAIMER.map((x, i) => x || DISCLAIMER[i]).filter(Boolean) : DISCLAIMER);\n  return `<div class=\"disclaimer\"><b>Important</b>${D.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['I took “The Rose of Love” test for couples: interesting and very accurate. Take it too, then we can compare:',\n                  'I found “The Rose of Love” test: 15 minutes, and you can see which roles in your couple are vivid and which have gone quieter. Give it a try:'],\n  'kompas':      ['I took the “Adaptation Compass” test for people living abroad. It really helps you see where you are now. Give it a try:',\n                  'I found the “Adaptation Compass” test: 10 minutes, and you can see what has already become a support in the new country and what is still quiet. Give it a try:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Try this test:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Know someone who might find this test useful too? Send them the link.</p>`\n    : `<div class=\"eyebrow\">Share</div><h3>Send the test to friends</h3><p>If the test was useful, send it to people it might help too. ${TEST_META.id === 'roza-lyubvi' ? 'Even better, invite your partner to take it and compare your results.' : 'Especially to those who have also recently moved.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Share</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Copy link</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Link to the test\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Link copied. Paste it into a message to a friend.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Copy the link from the field above.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\n/* копирайт внизу каждой страницы сайта */\n(function(){ const w = document.querySelector('.wrap'); if (!w || w.querySelector('.copy')) return;\n  const f = document.createElement('footer'); f.className = 'copy'; f.textContent = '© ' + new Date().getFullYear() + ' Iryna Voznesenskaya. All rights reserved.'; w.appendChild(f); })();\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  try { (JSON.parse(localStorage.getItem('irinaTestsSurvey') || '[]') || []).forEach(id => { const c = document.getElementById(id); if (c) c.checked = true; }); } catch(e){}\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Please mark how you heard about me.' : !a.interest.length ? 'Please mark what you are interested in.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    try { localStorage.setItem('irinaTestsSurvey', JSON.stringify([...document.querySelectorAll('input[data-sv]:checked')].map(i => i.id))); } catch(e){}\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n", "/* ---------- акварельная роза для «Розы любви» ----------\n   Три круга лепестков: внутри притяжение, в середине близость, снаружи ответственность.\n   Чем сильнее составляющая у пары, тем крупнее её лепестки. */\nconst ROSE = { f: ['#EEA9B3','#B0DCC0','#A6C4F0'], l: ['#C25468','#4E9A70','#3F6FBF'], leafF: '#C9E6D2', leafL: '#4E9A70' };\nlet roseN = 0;\nfunction roseSVG(sc){\n  const id = 'rose' + (++roseN), cx = 150, cy = 130;\n  const k = i => 0.55 + 0.45 * Math.max(sc[i], 2) / 40;           // масштаб круга\n  const petal = (w, h) => `M0 0 C ${w} ${-h * .2}, ${w * .9} ${-h * .9}, 0 ${-h} C ${-w * .9} ${-h * .9}, ${-w} ${-h * .2}, 0 0Z`;\n  const ring = (i, n, w, h, rot0) => {\n    const s = k(i); let out = '';\n    for (let j = 0; j < n; j++){\n      const rot = rot0 + j * 360 / n;\n      out += `<g transform=\"translate(${cx} ${cy}) rotate(${rot}) scale(${s.toFixed(3)})\"><g filter=\"url(#${id}w)\"><path d=\"${petal(w, h)}\" fill=\"${ROSE.f[i]}\" opacity=\".88\"/><path d=\"${petal(w * .6, h * .7)}\" fill=\"${ROSE.f[i]}\" opacity=\".7\"/></g>\n        <path d=\"${petal(w, h)}\" fill=\"none\" stroke=\"${ROSE.l[i]}\" stroke-width=\"${(1.6 / s).toFixed(2)}\"/></g>`;\n    }\n    return out;\n  };\n  return `<svg viewBox=\"0 0 300 300\" role=\"img\" aria-label=\"Your couple’s Rose of Love\"><defs>\n      <filter id=\"${id}w\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\"><feTurbulence type=\"fractalNoise\" baseFrequency=\"0.04\" numOctaves=\"3\" seed=\"${roseN * 5}\" result=\"n\"/><feDisplacementMap in=\"SourceGraphic\" in2=\"n\" scale=\"7\" result=\"d\"/><feGaussianBlur in=\"d\" stdDeviation=\"0.7\"/></filter>\n      <filter id=\"${id}b\"><feGaussianBlur stdDeviation=\"14\"/></filter></defs>\n    <circle cx=\"80\" cy=\"80\" r=\"55\" fill=\"${ROSE.f[0]}\" opacity=\".3\" filter=\"url(#${id}b)\"/>\n    <circle cx=\"225\" cy=\"200\" r=\"60\" fill=\"${ROSE.f[2]}\" opacity=\".3\" filter=\"url(#${id}b)\"/>\n    <path d=\"M150 190 C146 220 152 250 148 292\" fill=\"none\" stroke=\"${ROSE.leafL}\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n    <g filter=\"url(#${id}w)\"><path d=\"M149 240 C120 222 98 230 88 246 C112 258 134 254 149 240Z\" fill=\"${ROSE.leafF}\"/><path d=\"M150 214 C178 196 202 202 212 218 C190 232 166 228 150 214Z\" fill=\"${ROSE.leafF}\"/></g>\n    <path d=\"M149 240 C120 222 98 230 88 246 C112 258 134 254 149 240Z M150 214 C178 196 202 202 212 218 C190 232 166 228 150 214Z\" fill=\"none\" stroke=\"${ROSE.leafL}\" stroke-width=\"1.6\"/>\n    ${ring(2, 7, 46, 104, 0)}\n    ${ring(1, 6, 36, 78, 25)}\n    ${ring(0, 5, 26, 52, 10)}\n    <circle cx=\"${cx}\" cy=\"${cy}\" r=\"9\" fill=\"${ROSE.f[0]}\" stroke=\"${ROSE.l[0]}\" stroke-width=\"1.6\"/>\n  </svg>`;\n}\nfunction roseLegend(sc){\n  const n = ['Attraction','Closeness','Commitment'];\n  return `<div class=\"rose-legend\">${n.map((x, i) => `<span><i style=\"background:${ROSE.f[i]};border-color:${ROSE.l[i]}\"></i>${x} · ${sc[i]}</span>`).join('')}</div>`;\n}\n", "/* Items: own actions (first person) and the same actions as seen in the partner (third person). */\nconst SELF = {\n  f: [\n    ['I take the initiative in intimacy myself.',\n     'I pay him compliments as a man: about his looks, his strength, what attracts me to him.',\n     'I get ready for time with him so that I am attractive to him, not only “for going out” or for work.',\n     'I flirt with him: a look, a joke, a hint, a touch “just because”.',\n     'I hug and kiss him unhurriedly, not on the run.',\n     'I arrange time just for the two of us: a date, an evening without children, guests or phones.',\n     'I try something new together with him: a place, an activity, an experience.',\n     'I tell him or write to him that I want him and miss him.',\n     'I take care of myself (rest, body, mood) so that I come to him full of energy, not drained.',\n     'I put things aside when he asks me to spend time together.'],\n    ['I ask how his day went and listen to the end, without interrupting or giving advice.',\n     'I tell him about my feelings and worries, not only about tasks and news.',\n     'I thank him for specific actions, naming exactly what for.',\n     'I support him in front of other people: children, relatives, friends.',\n     'I consult him before making an important decision.',\n     'I talk with him without my phone for at least 20 minutes in a row.',\n     'I take an interest in his work, hobbies and plans and ask questions.',\n     'In an argument, I talk about my feelings and needs instead of blaming or criticising him.',\n     'After a fight, I take a step towards making up without waiting for him to take it first.',\n     'I laugh with him, remember good times and dream about our future.'],\n    ['I do what I promised, on time and without reminders.',\n     'I take care of the children and family matters so that he can rely on me.',\n     'I create a cosy, orderly home where we both feel good.',\n     'I care about his health and well-being without control or reproach.',\n     'I take part in planning the budget and major expenses.',\n     'I keep up family traditions and rituals: shared dinners, holidays, weekends.',\n     'I keep up relationships with his family and mine in a way that strengthens our family.',\n     'I let him be a father in his own way: I don’t take over, correct or criticise him in front of the children.',\n     'In a difficult situation, I stay close and take on my share.',\n     'I talk with him about our future: goals, plans, decisions for the years ahead.']\n  ],\n  m: [\n    ['I take the initiative in intimacy gently, paying attention to her mood.',\n     'I pay her compliments as a woman: about her beauty, about what attracts me to her.',\n     'I court her: flowers, small surprises, little signs of attention for no reason.',\n     'I ask her out on a date and organise everything myself.',\n     'I touch her tenderly outside the bedroom: I hug her, take her hand, stroke her back.',\n     'I take care of my appearance and fitness, partly for her sake.',\n     'I try something new together with her: a place, an activity, an experience.',\n     'I tell her or write to her that I want her and miss her.',\n     'I notice out loud how she looks: a new dress, her hair, her mood.',\n     'I create an atmosphere for the two of us: an evening without children, guests or phones, prepared by me.'],\n    ['I listen to her to the end, without interrupting or jumping straight to solutions.',\n     'I tell her about my feelings, doubts and worries, not only about facts.',\n     'I thank her for specific things, including the invisible work for the home and family.',\n     'I take her side in front of other people: children, relatives, friends.',\n     'I consult her before making an important decision.',\n     'I talk with her without my phone for at least 20 minutes in a row.',\n     'I take an interest in her work, friends, hobbies and plans and ask questions.',\n     'In an argument, I talk about my feelings calmly, without blaming her or withdrawing into silence.',\n     'After a fight, I take a step towards making up without waiting for her to take it first.',\n     'I laugh with her, remember good times and dream about our future.'],\n    ['I do what I promised, on time and without reminders.',\n     'I notice myself what needs doing at home and do it without her asking.',\n     'I spend time with the children personally: playing, talking, homework, walks.',\n     'I provide financial stability and talk openly with her about money.',\n     'I see household tasks through to the end: repairs, paperwork, appointments, breakdowns.',\n     'I look after the safety and health of the family, including my own.',\n     'I keep up family traditions and rituals: shared dinners, holidays, weekends.',\n     'I take over the children and the home so that she has time for herself.',\n     'In a difficult situation, I stay close instead of disappearing into work, the garage or my phone.',\n     'I talk with her about our future: goals, plans, decisions for the years ahead.']\n  ]\n};\nconst OTHER = {\n  m: [ // the man, as seen by the woman\n    ['He takes the initiative in intimacy gently, paying attention to my mood.',\n     'He pays me compliments as a woman: about my beauty, about what attracts him to me.',\n     'He courts me: flowers, small surprises, little signs of attention for no reason.',\n     'He asks me out on a date and organises everything himself.',\n     'He touches me tenderly outside the bedroom: he hugs me, takes my hand, strokes my back.',\n     'He takes care of his appearance and fitness, partly for my sake.',\n     'He tries something new together with me: a place, an activity, an experience.',\n     'He tells me or writes to me that he wants me and misses me.',\n     'He notices out loud how I look: a new dress, my hair, my mood.',\n     'He creates an atmosphere for the two of us: an evening without children, guests or phones, prepared by him.'],\n    ['He listens to me to the end, without interrupting or jumping straight to solutions.',\n     'He tells me about his feelings, doubts and worries, not only about facts.',\n     'He thanks me for specific things, including the invisible work for the home and family.',\n     'He takes my side in front of other people: children, relatives, friends.',\n     'He consults me before making an important decision.',\n     'He talks with me without his phone for at least 20 minutes in a row.',\n     'He takes an interest in my work, friends, hobbies and plans and asks questions.',\n     'In an argument, he talks about his feelings calmly, without blaming me or withdrawing into silence.',\n     'After a fight, he takes a step towards making up without waiting for me to take it first.',\n     'He laughs with me, remembers good times and dreams about our future.'],\n    ['He does what he promised, on time and without reminders.',\n     'He notices himself what needs doing at home and does it without my asking.',\n     'He spends time with the children personally: playing, talking, homework, walks.',\n     'He provides financial stability and talks openly with me about money.',\n     'He sees household tasks through to the end: repairs, paperwork, appointments, breakdowns.',\n     'He looks after the safety and health of the family, including his own.',\n     'He keeps up family traditions and rituals: shared dinners, holidays, weekends.',\n     'He takes over the children and the home so that I have time for myself.',\n     'In a difficult situation, he stays close instead of disappearing into work, the garage or his phone.',\n     'He talks with me about our future: goals, plans, decisions for the years ahead.']\n  ],\n  f: [ // the woman, as seen by the man\n    ['She takes the initiative in intimacy herself.',\n     'She pays me compliments as a man: about my looks, my strength, what attracts her to me.',\n     'She gets ready for time with me so that she is attractive to me, not only “for going out” or for work.',\n     'She flirts with me: a look, a joke, a hint, a touch “just because”.',\n     'She hugs and kisses me unhurriedly, not on the run.',\n     'She arranges time just for the two of us: a date, an evening without children, guests or phones.',\n     'She tries something new together with me: a place, an activity, an experience.',\n     'She tells me or writes to me that she wants me and misses me.',\n     'She takes care of herself (rest, body, mood) and comes to me full of energy, not drained.',\n     'She puts things aside when I ask her to spend time together.'],\n    ['She asks how my day went and listens to the end, without interrupting or giving advice.',\n     'She tells me about her feelings and worries, not only about tasks and news.',\n     'She thanks me for specific actions, naming exactly what for.',\n     'She supports me in front of other people: children, relatives, friends.',\n     'She consults me before making an important decision.',\n     'She talks with me without her phone for at least 20 minutes in a row.',\n     'She takes an interest in my work, hobbies and plans and asks questions.',\n     'In an argument, she talks about her feelings and needs instead of blaming or criticising me.',\n     'After a fight, she takes a step towards making up without waiting for me to take it first.',\n     'She laughs with me, remembers good times and dreams about our future.'],\n    ['She does what she promised, on time and without reminders.',\n     'She takes care of the children and family matters so that I can rely on her.',\n     'She creates a cosy, orderly home where we both feel good.',\n     'She cares about my health and well-being without control or reproach.',\n     'She takes part in planning the budget and major expenses.',\n     'She keeps up family traditions and rituals: shared dinners, holidays, weekends.',\n     'She keeps up relationships with my family and hers in a way that strengthens our family.',\n     'She lets me be a father in my own way: she doesn’t take over, correct or criticise me in front of the children.',\n     'In a difficult situation, she stays close and takes on her share.',\n     'She talks with me about our future: goals, plans, decisions for the years ahead.']\n  ]\n};\nconst ROLES = { f: ['Lover','Wife','Mother'], m: ['Lover','Husband','Father'] };\nconst COMP = ['Attraction','Closeness','Commitment'];\nconst VARS = ['--passion','--close','--resp'];\nconst SOFT = ['--passion-soft','--close-soft','--resp-soft'];\nconst LABELS = ['never','1–2 times','sometimes','often','almost always'];\n\n/* ---------- content library ---------- */\nconst ROLE_INFO = {\n  f: ['She is the woman he desires. This role is about desire, play, lightness and interest in her man. She keeps the spark alive in the couple and does not let the relationship turn into just living side by side.',\n      'She is a friend and ally. This role is about trust, conversations, support and the feeling “we are one team”. She gives a man the feeling that he is understood at home.',\n      'She is the anchor of the family. This role is about reliability, care, home and a shared future. It is not about being a mother to her husband, but about mature responsibility for your shared world.'],\n  m: ['He is the man who desires and pursues. This role is about courtship, initiative, tenderness and admiration for his woman. Next to him, a woman feels desired.',\n      'He is a friend and partner. This role is about being able to listen, share feelings and take her side. He gives a woman the feeling that she is not alone.',\n      'He is an anchor and protector. This role is about keeping his word, home, children, money and the future. Next to him, life feels calm and safe.']\n};\nconst LV = [\n  ['Right now the “{R}” role is quiet. This happens in almost every couple: desire, play and courtship quietly slip into the background when there is a lot of tiredness, everyday routine, children or unspoken hurt. It is not about a lack of love, but about this role not having been given space for a long time. The good news: it responds even to small steps.',\n   'In the “{R}” role, {N} shows up from time to time. The spark is there, but it depends on mood and free time. Under stress and tiredness this role is the first to fade, so it is worth supporting it consciously rather than waiting for inspiration.',\n   '{N} shines in the “{R}” role. Desire, interest and play live in actions, not only in feelings. This is what keeps a couple together as a man and a woman, not only as a team.'],\n  ['Right now closeness in actions is quiet. There are fewer heart-to-heart talks, less gratitude and support, and communication often comes down to tasks. That is very understandable in a busy life. But closeness is easy to bring back: sometimes 20 minutes of conversation without phones is enough.',\n   '{N} shows closeness, but not consistently. Good conversations happen when there is time and the mood is right. In tense periods, communication narrows down to tasks, and the partner may feel misunderstood.',\n   '{N} is truly present in the “{R}” role: listens, shares, thanks, supports. With a partner like this you feel you are not alone. This is the foundation of trust in a couple.'],\n  ['Right now commitment in actions is quiet. Promises, the home, shared plans and the future are still in the shadows. Perhaps there simply is not enough energy for it, or this is how the roles have come to be divided. It is worth gently talking with your partner about who wants to be responsible for what.',\n   '{N} shows commitment, but not in everything. In some things the partner can rely on {N}, in others they have to remind or take everything on themselves. It helps to agree on this calmly, so that no one feels alone with the cares.',\n   '{N} reliably shows up in the “{R}” role: keeps their word, takes care of the home and the future, stays close in hard moments. This gives the couple a sense of safety. It is only important that responsibility does not crowd out the other roles.']\n];\nconst LV_NAME = ['still quiet','shows up from time to time','shines brightly'];\nconst RECS = {\n  f: [['Once a week, arrange an evening for the two of you: no children, guests or phones. The initiative is yours.',\n       'Tell him what attracts you to him as a man. Be specific: his hands, his voice, the way he does something.',\n       'Find 15 minutes a day for yourself: rest, body, mood. It matters to come to your man full of energy, not drained.'],\n      ['Every day, ask how his day went and listen to the end without giving advice.',\n       'Thank him for specific actions: not just “thank you”, but “thank you for … today”.',\n       'Share feelings, not only news: “I was worried today because…”.'],\n      ['Agree on two or three family rituals: a shared dinner, a Sunday walk, a planning evening.',\n       'Let him be a father in his own way: don’t correct him or take over in front of the children.',\n       'Once a month, talk about the future: goals, money, plans for the year.']],\n  m: [['Ask her out on a date and organise everything yourself: the place, the time, the children.',\n       'Every day, notice out loud how she looks and what attracts you to her.',\n       'Touch her tenderly outside the bedroom: a hug, holding her hand, just because.'],\n      ['Listen to her to the end without jumping to solutions. Ask: “Do you need advice right now, or support?”',\n       'Talk about your feelings and worries, not only about facts and tasks.',\n       'Thank her for the invisible work: home, children, relatives, everyday life.'],\n      ['Notice yourself what needs doing at home, and do it without her asking.',\n       'Spend time with the children personally, without your phone, for at least 30 minutes a day.',\n       'Talk with her openly about money and the future: plans, decisions, fears.']]\n};\nconst KEEP = 'This role is already working. Keep doing what you are doing, and make sure it does not crowd out the others.';\nconst PAIR = [\n  { strong:'There is desire and play between you, and you both invest in it. This is rare for couples who have been together a long time. Protect your time together, even when life gets busy.',\n    weak:'Attraction has gone quiet for both of you. Usually it is not a lack of feelings, but tiredness, everyday routine and children. The good news: attraction comes back through actions. Start small: a date once a week and touches for no reason.',\n    mid:'Attraction is alive, but it depends on chance. To keep the spark from fading, it needs a place in the calendar: planned time together works better than waiting for the right mood.',\n    gap:'{A} invests noticeably more in attraction. Over time, the one who keeps reaching out feels hurt and lonely, while the one who responds less may feel pressured. It is important to calmly find out what is getting in the way: tiredness, hurt, insecurity or a different understanding of what desire is.' },\n  { strong:'You are friends and allies: you talk, support and thank each other. This is the best protection a couple has against crises.',\n    weak:'Closeness has gone quiet for both of you. You are side by side, but each lives with their feelings separately. Start with 20 minutes of conversation a day without phones and the question “How are you, really?”.',\n    mid:'There is closeness, but it lacks regularity. Agree on a small daily conversation ritual so that your communication does not come down to tasks.',\n    gap:'{A} invests more in closeness: asks, listens, shares. The one who opens up more may feel unheard. The other partner often simply lacks the skill or an example. A direct request helps: “It matters to me that you ask me about…”.' },\n  { strong:'You are both reliable: you keep your word and take care of the home and the future. The couple feels safe. Make sure responsibility does not eat up the time for passion and closeness.',\n    weak:'Commitment is sagging for both of you. Promises are forgotten, plans are postponed, the future is not discussed. Start with one step: a family planning evening once a month.',\n    mid:'Responsibilities are shared, but unevenly and not always openly. Discuss who is responsible for what, so that no one feels they are carrying more.',\n    gap:'{A} carries more responsibility for your shared world. This is a direct path to tiredness and irritation for one of you and to passivity for the other. Sit down together and redistribute the areas: home, money, children, relatives, plans.' }\n];\nconst PAIR_TITLE = { strong:'Shared strength', weak:'Shared area of growth', mid:'There, but left to chance', gap:'Different contributions' };\nconst QUEST = [\n  ['When did you last feel desired?','What dampens desire in your couple: tiredness, hurt, everyday routine?','What was your best date like, and what did you do differently then?'],\n  ['What have you not really talked about for a long time?','Do you feel heard? In which moments most of all?','What do you keep to yourself and not tell your partner?'],\n  ['In what can you rely on your partner, and in what not?','What shared decision have you been putting off for a long time?','How do you see your couple in five years?']\n];\nconst TYPES = {\n  '111':['Complete love','I want you, I know you, I choose you. All three components are alive in your couple: attraction, closeness and commitment. This is the most stable form of love, but it too needs care. The main risk is to relax and stop doing what already works.'],\n  '110':['Romantic love','There is passion and closeness between you: you feel good together, you are interesting to each other and you talk a lot. The anchor is less visible: shared plans, reliability, the future. Such relationships are bright and warm, but in a hard period the foundation may not be strong enough.'],\n  '011':['A union of friends','You are reliable partners and friends: you support each other and run your shared world together. Attraction has moved into the background. Many long-term couples drift here without noticing. The risk is becoming “brother and sister”. The good news: passion comes back when it is given time and attention again.'],\n  '101':['Whirlwind love','There is passion and commitment, but little real closeness and few heart-to-heart talks. You are together and drawn to each other, but you do not always know what is going on inside your partner. The way forward for your couple lies in building trust and openness.'],\n  '100':['Falling in love','There is attraction between you, while closeness and a shared anchor are still being built. It is bright and alive. For the relationship to stand the test of time, you need to build friendship and a shared future: talk, make agreements, keep your word.'],\n  '010':['Friendship and fondness','You feel warm and at ease with each other, you can talk and support each other. But attraction and a shared future show up only weakly in your actions. The task is to bring desire back into the couple and make your shared plans real.'],\n  '001':['Love worn out by cares','You reliably run your shared world, but passion and closeness are quiet right now. This is a very common state when there are many children, a lot of work and many worries. In Sternberg’s model it is called “empty love”, but in reality love has not gone anywhere, it is simply tired. It can be revived with small actions in the roles of lover and spouse.'],\n  '000':['A triangle waiting for attention','Right now none of the components shows up strongly. This is not a verdict: a couple often looks like this in a difficult period, when tired or after a crisis. It is a convenient point to start from. Even small actions will be noticed.']\n};\n\n/* ---------- state ---------- */\nlet g = null, step = 0, ans = [], names = {f:'', m:''};\nlet last = null;\nconst $ = id => document.getElementById(id);\nconst css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();\nconst other = x => x === 'f' ? 'm' : 'f';\nconst sum = a => a.reduce((x,y) => x+y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst lvl = s => s <= 15 ? 0 : s <= 27 ? 1 : 2;\nconst typeOf = sc => TYPES[sc.map(s => s >= 28 ? 1 : 0).join('')];\nconst fill = (t, o) => t.replace(/\\{(\\w)\\}/g, (_, k) => o[k]);\n\ndocument.querySelectorAll('.choice').forEach(b => b.addEventListener('click', () => {\n  g = b.dataset.g; resetInvite(); window.__leadCountry = '';\n  const me = $('nameMe').value.trim(), p = $('nameP').value.trim();\n  names[g] = me || (g === 'f' ? 'Woman' : 'Man');\n  names[other(g)] = p || (g === 'f' ? 'Man' : 'Woman');\n  step = 0; ans = Array.from({length:6}, () => Array(10).fill(null));\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0,0);\n}));\n\nfunction stepInfo(s){\n  const self = s < 3, k = s % 3;\n  const who = self ? g : other(g);\n  const items = self ? SELF[g][k] : OTHER[who][k];\n  const P = esc(names[other(g)]);\n  const pr = g === 'f' ? 'he' : 'she';\n  const tag = self ? 'Part 1 · What I do' : `Part 2 · What ${P} does`;\n  const title = self ? `Me as a ${ROLES[g][k].toLowerCase()}` : `${P} as a ${ROLES[who][k].toLowerCase()}`;\n  const sub = self\n    ? ['What you do to keep desire and interest alive between you.','What you do so that you stay friends and a team.','What you do so that your partner can rely on you.'][k]\n    : [`How ${pr} keeps desire and interest alive between you.`,`How ${pr} shows closeness and friendship towards you.`,`How much of an anchor ${pr} is for you.`][k];\n  return { k, items, tag, title, sub };\n}\nfunction renderStep(){\n  const info = stepInfo(step);\n  document.documentElement.style.setProperty('--accent', `var(${VARS[info.k]})`);\n  $('stepLabel').textContent = `Step ${step+1} of 6`;\n  $('partTag').innerHTML = info.tag;\n  $('roleTitle').innerHTML = `${info.title} <span class=\"muted\" style=\"font-size:.6em\">· ${COMP[info.k].toLowerCase()}</span>`;\n  $('roleTitle').style.color = `var(${VARS[info.k]})`;\n  $('roleSub').textContent = info.sub + ' Over the last 4 weeks.';\n  const list = $('qlist'); list.innerHTML = '';\n  info.items.forEach((t, i) => {\n    const q = document.createElement('div'); q.className = 'q';\n    q.innerHTML = `<p><span class=\"n\">${step*10+i+1}.</span>${t}</p><div class=\"opts\" role=\"group\" aria-label=\"Rating\"></div>`;\n    const opts = q.querySelector('.opts');\n    for (let v = 0; v <= 4; v++){\n      const o = document.createElement('button'); o.className = 'opt'; o.id = `q${step}-${i}-${v}`;\n      o.setAttribute('aria-pressed', ans[step][i] === v ? 'true' : 'false');\n      o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n      o.addEventListener('click', () => { ans[step][i] = v;\n        opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false'));\n        update(); });\n      opts.appendChild(o);\n    }\n    list.appendChild(q);\n  });\n  $('next').textContent = step === 5 ? 'Show my report' : (step === 2 ? 'Go to part 2' : 'Next');\n  update();\n}\nfunction update(){\n  const done = ans.flat().filter(v => v !== null).length;\n  $('countLabel').textContent = `${done} of 60`;\n  $('prog').style.width = (done/60*100) + '%';\n  $('next').disabled = ans[step].some(v => v === null);\n}\n$('next').addEventListener('click', () => { if (step < 5){ step++; renderStep(); window.scrollTo(0,0); } else showResult(); });\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0,0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- pictures ---------- */\nfunction icon(k, color){\n  const p = [\n    `<path d=\"M12.6 1.5c1.2 4.2 6.4 6.6 6.4 12.6a7 7 0 0 1-14 0c0-3.6 2.3-5.4 3-8.6 1.5 1.3 2.5 3.1 2.6 5.2 1.6-2.7 2.6-5.6 2-9.2z\" fill=\"${color}\"/>`,\n    `<circle cx=\"9\" cy=\"12\" r=\"5.6\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.4\"/><circle cx=\"15\" cy=\"12\" r=\"5.6\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.4\"/>`,\n    `<path d=\"M3 11.2 12 3.5l9 7.7V21h-6.2v-5.6H9.2V21H3z\" fill=\"${color}\"/>`][k];\n  return `<svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" aria-hidden=\"true\">${p}</svg>`;\n}\nfunction venn(){\n  const c = [css('--passion'), css('--close'), css('--resp')], ink = css('--ink');\n  return `<svg viewBox=\"0 0 300 260\" role=\"img\" aria-label=\"Three components of love\">\n    <circle cx=\"150\" cy=\"92\" r=\"78\" fill=\"${c[0]}\" fill-opacity=\".55\"/>\n    <circle cx=\"104\" cy=\"170\" r=\"78\" fill=\"${c[1]}\" fill-opacity=\".55\"/>\n    <circle cx=\"196\" cy=\"170\" r=\"78\" fill=\"${c[2]}\" fill-opacity=\".55\"/>\n    <text x=\"150\" y=\"58\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"${ink}\">Attraction</text>\n    <text x=\"70\" y=\"200\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"${ink}\">Closeness</text>\n    <text x=\"232\" y=\"200\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-weight=\"700\" font-size=\"13\" fill=\"${ink}\">Commitment</text>\n    <text x=\"150\" y=\"150\" text-anchor=\"middle\" font-family=\"Forum, Georgia, serif\" font-size=\"18\" fill=\"${ink}\">love</text>\n  </svg>`;\n}\nfunction triSVG(polys, labelVals){\n  const W = 420, H = 320, cx = 210, cy = 178, R = 116;\n  const ang = [-90, 30, 150].map(d => d*Math.PI/180);\n  const pt = (k, f) => [cx + R*f*Math.cos(ang[k]), cy + R*f*Math.sin(ang[k])];\n  const poly = f => [0,1,2].map(k => pt(k, f).map(n => n.toFixed(1)).join(',')).join(' ');\n  const line = css('--line'), muted = css('--muted');\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Triangle\">`;\n  s += `<polygon points=\"${poly(1)}\" fill=\"${css('--paper')}\" />`;\n  [0.25,0.5,0.75,1].forEach(f => s += `<polygon points=\"${poly(f)}\" fill=\"none\" stroke=\"${line}\" stroke-width=\"${f===1?1.6:1}\"/>`);\n  [0,1,2].forEach(k => { const [x,y] = pt(k,1); s += `<line x1=\"${cx}\" y1=\"${cy}\" x2=\"${x}\" y2=\"${y}\" stroke=\"${line}\"/>`; });\n  polys.forEach(p => {\n    const pts = [0,1,2].map(k => pt(k, Math.max(p.sc[k],1)/40).map(n => n.toFixed(1)).join(',')).join(' ');\n    s += `<polygon points=\"${pts}\" fill=\"${p.color}\" fill-opacity=\"${p.fill ?? .22}\" stroke=\"${p.color}\" stroke-width=\"3\" stroke-linejoin=\"round\" ${p.dash ? 'stroke-dasharray=\"7 5\"' : ''}/>`;\n    [0,1,2].forEach(k => { const [x,y] = pt(k, Math.max(p.sc[k],1)/40); s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"5\" fill=\"${p.color}\"/>`; });\n  });\n  const lab = [[cx, 30, 'middle'], [pt(1,1)[0]+10, pt(1,1)[1]+30, 'middle'], [pt(2,1)[0]-10, pt(2,1)[1]+30, 'middle']];\n  lab.forEach(([x,y,a], k) => {\n    s += `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${a}\" font-family=\"Forum, Georgia, serif\" font-size=\"17\" fill=\"${css(VARS[k])}\">${labelVals[k][0]}</text>`;\n    s += `<text x=\"${x}\" y=\"${y+16}\" text-anchor=\"${a}\" font-family=\"Manrope, sans-serif\" font-size=\"11\" fill=\"${muted}\">${labelVals[k][1]}</text>`;\n  });\n  return s + '</svg>';\n}\nconst bar = (v, color) => `<div class=\"bar\"><i style=\"width:${v/40*100}%;background:${color}\"></i></div>`;\n\n/* ---------- report ---------- */\nfunction compute(){\n  const selfSc = ans.slice(0,3).map(sum), partSc = ans.slice(3).map(sum);\n  const isF = g === 'f';\n  const W = isF ? selfSc : partSc, M = isF ? partSc : selfSc;\n  const Wa = isF ? ans.slice(0,3) : ans.slice(3), Ma = isF ? ans.slice(3) : ans.slice(0,3);\n  const avg = [0,1,2].map(k => Math.round((W[k] + M[k]) / 2));\n  return { selfSc, partSc, W, M, Wa, Ma, avg, isF };\n}\n\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const { W, M, Wa, Ma, avg, isF, selfSc, partSc } = r;\n  const NF = esc(names.f), NM = esc(names.m), NS = esc(names[g]), NP = esc(names[other(g)]);\n  const her = css('--her'), him = css('--him'), plum = css('--plum');\n  const [pType, pText] = typeOf(avg);\n  const date = new Date().toLocaleDateString(DATE_LOCALE, {day:'numeric', month:'long', year:'numeric'});\n  const B = [];\n\n  // cover\n  B.push({ html: `<div class=\"blk hero\"><div class=\"split\">\n      <div class=\"stack\" style=\"gap:10px\"><div class=\"eyebrow\">The Rose of Love · report</div>\n        <div class=\"names\">${NF} & ${NM}</div>\n        <h1>${pType}</h1>\n        <p class=\"note\">${date} · completed by${isF ? '' : ''}: ${NS}</p></div>\n      <div class=\"fig\">${roseSVG(avg)}${roseLegend(avg)}</div></div></div>` });\n  B.push({ html: `<div class=\"blk\"><h3>What this means for your couple</h3><p>${pText}</p>\n      <p class=\"note\">Your couple’s type is based on the average scores of both partners. A component counts as strong from 28 points out of 40.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><h2>Your couple’s triangle</h2><div class=\"split\">\n      <div class=\"fig\" style=\"flex-basis:320px\">${triSVG([{sc:W,color:her,fill:.18},{sc:M,color:him,fill:.18},{sc:avg,color:plum,fill:0,dash:true}], [0,1,2].map(k => [COMP[k], `couple: ${avg[k]} / 40`]))}</div>\n      <div class=\"stack\" style=\"gap:12px\">\n        <div class=\"legend\"><span><i style=\"background:${her}\"></i>${NF}</span><span><i style=\"background:${him}\"></i>${NM}</span><span><i style=\"border:2px dashed ${plum}\"></i>Couple on average</span></div>\n        ${[0,1,2].map(k => `<div class=\"stack\" style=\"gap:6px\"><div class=\"row\" style=\"gap:8px\">${icon(k, css(VARS[k]))}<b style=\"font-family:var(--display);font-weight:400;font-size:1.15rem;color:var(${VARS[k]})\">${COMP[k]}</b></div>\n          <div class=\"duo\"><span>${NF}</span>${bar(W[k], her)}<b style=\"color:${her}\">${W[k]}</b><span>${NM}</span>${bar(M[k], him)}<b style=\"color:${him}\">${M[k]}</b></div></div>`).join('')}\n      </div></div>\n      <p class=\"note\">The partner’s triangle is based on the perception of the person who took the test (${NS}). ${NP} may see themselves differently.</p></div>` });\n  B.push({ html: testInfoHtml() });\n\n  // portraits\n  const portrait = (gg, sc, color, softVar) => {\n    const N = esc(names[gg]); const [tn] = typeOf(sc);\n    const out = [{ newPage:true, html: `<div class=\"blk\" style=\"background:var(${softVar});border:none\"><div class=\"split\">\n        <div class=\"stack\" style=\"gap:8px\"><div class=\"eyebrow\">Portrait · ${gg === g ? 'self-assessment' : 'through the partner’s eyes'}</div>\n          <h2 style=\"color:${color}\">${N}</h2>\n          <p>${gg==='f' ? 'Lover, wife, mother' : 'Lover, husband, father'}. Total <b>${sum(sc)}</b> of 120. Shape of the triangle: <b>${tn}</b>.</p>\n          ${sc.map((s,k) => `<div class=\"stack\" style=\"gap:4px\"><div class=\"row\" style=\"justify-content:space-between\"><span>${ROLES[gg][k]}</span><b style=\"color:var(${VARS[k]})\">${s} / 40</b></div>${bar(s, css(VARS[k]))}</div>`).join('')}\n        </div>\n        <div class=\"fig\">${triSVG([{sc, color}], [0,1,2].map(k => [`${ROLES[gg][k]} · ${sc[k]}`, LV_NAME[lvl(sc[k])]]))}</div></div></div>` }];\n    sc.forEach((s, k) => {\n      const l = lvl(s);\n      const recs = l === 2 ? `<p class=\"recs\" style=\"padding-left:14px;list-style:none\">${KEEP}</p>`\n        : `<div class=\"recs-t\">What will help</div><ul class=\"recs\">${RECS[gg][k].map(x => `<li>${x}</li>`).join('')}</ul>`;\n      out.push({ html: `<div class=\"blk role-blk\" style=\"--c:var(${VARS[k]});--cs:var(${SOFT[k]})\">\n        <div class=\"role-head\"><div class=\"ico\">${icon(k, css(VARS[k]))}</div><h3>${ROLES[gg][k]}</h3>\n          <span class=\"pill\" style=\"background:var(${VARS[k]})\">${LV_NAME[l]}</span><span class=\"sc\">${s} / 40</span></div>\n        <p class=\"note\" style=\"font-style:italic\">${ROLE_INFO[gg][k]}</p>\n        <p>${fill(LV[k][l], {N, R: ROLES[gg][k].toLowerCase()})}</p>\n        ${recs}</div>` });\n    });\n    return out;\n  };\n  B.push(...portrait('f', W, her, '--her-soft'));\n  B.push(...portrait('m', M, him, '--him-soft'));\n\n  // interaction\n  B.push({ newPage:true, html: `<div class=\"blk plain\"><div class=\"eyebrow\">How you interact</div><h2>How you meet each other</h2>\n    <p>For each component of love, the actions of both partners are compared. What matters is not only how much each of you invests, but also how mutual the investment is.</p></div>` });\n  [0,1,2].forEach(k => {\n    const w = W[k], m = M[k], d = w - m;\n    let kind, A = '';\n    if (Math.abs(d) >= 8){ kind = 'gap'; A = d > 0 ? NF : NM; }\n    else if (w >= 28 && m >= 28) kind = 'strong';\n    else if (w <= 20 && m <= 20) kind = 'weak';\n    else kind = 'mid';\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:var(${VARS[k]});--cs:var(${SOFT[k]})\">\n      <div class=\"role-head\"><div class=\"ico\">${icon(k, css(VARS[k]))}</div><h3>${COMP[k]}</h3>\n        <span class=\"pill\" style=\"background:var(${VARS[k]})\">${PAIR_TITLE[kind]}</span><span class=\"sc\">${avg[k]} / 40</span></div>\n      <div class=\"duo\"><span>${ROLES.f[k]} · ${NF}</span>${bar(w, her)}<b style=\"color:${her}\">${w}</b><span>${ROLES.m[k]} · ${NM}</span>${bar(m, him)}<b style=\"color:${him}\">${m}</b></div>\n      <p>${fill(PAIR[k][kind], {A})}</p></div>` });\n  });\n\n  // balance and traps\n  const notes = [];\n  const tW = sum(W), tM = sum(M), dT = tW - tM;\n  if (Math.abs(dT) <= 8) notes.push(['--resp','--resp-soft','Balance of giving', `${NF} and ${NM} invest in the relationship roughly equally (${tW} and ${tM} of 120). This is a good foundation: neither of you feels like the only one “carrying” the couple. Keep up this balance and notice each other’s contribution out loud.`]);\n  else {\n    const A = dT > 0 ? NF : NM, Bn = dT > 0 ? NM : NF;\n    notes.push(['--close','--close-soft','Contributions are still uneven', `${A} invests noticeably more in the relationship (${Math.max(tW,tM)} versus ${Math.min(tW,tM)} of 120). Over time it can become hard for the one who gives more, and the other may not even notice. Two things are worth checking. Does ${Bn} really do less, or show up in ways that are hard to notice? And does ${A} leave room for the partner’s actions, or take everything on in advance?`]);\n  }\n  if ((W[2] >= 28 && W[0] <= 15) || (M[2] >= 28 && M[0] <= 15)) notes.push(['--passion','--passion-soft','When the parents overshadow the couple', 'The parent role takes up a lot of space right now, while the lover role is quieter. You are a great team in everyday life, and it is worth being simply a couple more often. This is the most common scenario after children are born. The way out is to protect time for just the two of you as seriously as the children’s activities.']);\n  if (Ma[2][3] + Ma[2][4] >= 6 && Ma[2][2] + Ma[2][8] <= 3) notes.push(['--him','--him-soft','When providing replaces being present', `${NM} invests a lot in money and solving problems, but less in simply being there. A man sincerely believes that this is how he shows love. But a woman and children feel love above all through time, attention and conversation.`]);\n  if (sum(Wa[2].slice(0,4)) >= 12 && (Wa[2][7] <= 1 || W[0] <= 15)) notes.push(['--her','--her-soft','When care turns into control', `A woman’s care easily turns into control: remind, check, correct. With care like this, a man stops feeling like a man, and the woman gets tired of being responsible for two. Trust helps: let him do it his own way, even if it is not perfect.`]);\n  notes.forEach(([c, cs, t, x]) => B.push({ html: `<div class=\"callout\" style=\"--c:var(${c});--cs:var(${cs})\"><h3>${t}</h3><p>${x}</p></div>` }));\n\n  // plan\n  const weakest = selfSc.indexOf(Math.min(...selfSc));\n  const low = SELF[g][weakest].map((t,i) => [t, ans[weakest][i]]).sort((a,b) => a[1]-b[1]).slice(0,2);\n  const partStrong = partSc.indexOf(Math.max(...partSc));\n  const pairWeak = avg.indexOf(Math.min(...avg));\n  const ritual = ['Once a week, a date for the two of you: no children, guests or phones.','20 minutes of conversation every evening: “How are you, really?”','A family planning evening once a month: home, money, children, dreams.'][pairWeak];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">4-week plan</div><h2>Small steps that change a couple</h2>\n    <div class=\"steps\">\n      <div><span class=\"num\">1</span><div><b>Your step: the “${ROLES[g][weakest]}” role</b><p>This is your quietest role right now. Choose one action and do it at least twice a week:</p>\n        <ul class=\"clean\" style=\"margin-top:6px\">${low.map(([t]) => `<li>${t.replace(/^I /,'').replace(/^./, c => c.toUpperCase())}</li>`).join('')}</ul></div></div>\n      <div><span class=\"num\">2</span><div><b>Thank your partner</b><p>Your partner shows up most strongly in the “${ROLES[other(g)][partStrong]}” role. Say so out loud and name a specific action. When a contribution is noticed, people want to keep it up.</p></div></div>\n      <div><span class=\"num\">3</span><div><b>A shared ritual for your couple: ${COMP[pairWeak].toLowerCase()}</b><p>${ritual}</p></div></div>\n      <div><span class=\"num\">4</span><div><b>In 4 weeks</b><p>Take the test again, ideally together, and compare your triangles.</p></div></div>\n    </div></div>` });\n\n  B.push({ html: `<div class=\"blk\"><h2>Questions to reflect on</h2><p class=\"note\">Answer them for yourself in writing, then choose one question and discuss it with your partner.</p>\n    <div class=\"qgrid\">${[0,1,2].map(k => `<div style=\"--c:var(${VARS[k]});--cs:var(${SOFT[k]})\"><div class=\"row\" style=\"gap:8px\">${icon(k, css(VARS[k]))}<h3>${COMP[k]}</h3></div><ul>${QUEST[k].map(q => `<li>${q}</li>`).join('')}</ul></div>`).join('')}</div></div>` });\n  B.push({ html: `<div class=\"blk\"><h3>Questions to talk about as a couple</h3><ul class=\"clean\">\n    <li>Where are our triangles similar, and where do they differ? What surprised you?</li>\n    <li>In which role do you feel me most strongly? And in which do you miss me?</li>\n    <li>What one action of mine would you notice already this week?</li>\n    <li>What was our couple like when all three roles were alive? What did we do differently then?</li></ul>\n    <p class=\"note\">Different scores are not a reason to argue, but a map of the language in which each of you reads love.</p></div>` });\n\n  const nmSelf = ['Woman','Man'].includes(names[g]) ? '' : names[g];\n  B.push({ html: inviteHtml({\n    name: nmSelf,\n    country: window.__leadCountry || '',\n    interest: (typeof surveyAnswers === 'function') ? surveyAnswers().interest : [],\n    focus: {\n      psy: ['bring attraction and desire back into your relationship','bring back closeness and heart-to-heart talks','become a reliable support for each other'][pairWeak],\n      coach: ['understand yourself and your wishes in relationships better','trust yourself more and open up to the people close to you','find a balance between caring for others and caring for yourself'][pairWeak]\n    }\n  }) });\n  B.push({ html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n\n  r.pType = pType; r.notes = notes.map(n => n[2]);\n  return B;\n}\n\nfunction showResult(){\n  const blocks = buildBlocks();\n  $('report').innerHTML = blocks.map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; $('status').hidden = true; window.scrollTo(0,0);\n}\n\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => (['Woman','Man'].includes(names[g]) ? '' : names[g]),\n  fileBase: () => 'Roza_lyubvi',\n  fileNames: () => [names.f, names.m].filter(n => !['Woman','Man'].includes(n)),\n  payload: () => {\n    const r = last, scores = {};\n    ROLES.f.forEach((x, k) => scores['Женщина: ' + x] = r.W[k]);\n    ROLES.m.forEach((x, k) => scores['Мужчина: ' + x] = r.M[k]);\n    COMP.forEach((x, k) => scores['Пара: ' + x] = r.avg[k]);\n    scores['Всего: женщина'] = sum(r.W); scores['Всего: мужчина'] = sum(r.M);\n    return { result: r.pType, scores, notes: `проходил${g === 'f' ? 'а женщина' : ' мужчина'}` + (r.notes.length ? '; ' + r.notes.join('; ') : '') };\n  }\n};\n\n/* значки на плитках ролей на стартовой странице */\ndocument.querySelectorAll('.roles .role').forEach((el, k) => {\n  const b = el.querySelector('b'); if (!b || k > 2) return;\n  const w = document.createElement('div'); w.className = 'ri';\n  w.innerHTML = icon(k, css(VARS[k])); b.parentNode.insertBefore(w, b); w.appendChild(b);\n});\n", "/* =====================================================================\n   Общая анкета перед PDF, отправка в Google Таблицу и сборка PDF.\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   ===================================================================== */\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions\" style=\"margin-top:18px\">\n    <h3>Get your report as a PDF</h3>\n    <p>A beautiful PDF of your report without the test questions: pictures, descriptions, recommendations, a 4-week plan and questions to reflect on. Leave your contact details and the file will download straight away.</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">Name *</label><input id=\"fName\" maxlength=\"40\" required autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">E-mail *</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" required autocomplete=\"email\"></div>\n      </div>\n      <div class=\"field\"><label for=\"fContact\">Telegram or WhatsApp</label><input id=\"fContact\" maxlength=\"60\" placeholder=\"@username or +41 …\"></div>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fCountry\">Country *</label><select id=\"fCountry\" required><option value=\"\">Choose your country</option></select></div>\n        <div class=\"field\"><label for=\"fCity\">City</label><input id=\"fCity\" maxlength=\"40\" autocomplete=\"address-level2\"></div>\n      </div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\" required> <span>I agree to the processing of my data to send me my results and to contact me *</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>I would like to receive useful materials about relationships, adaptation and life abroad</span></label>\n      <p class=\"err\" id=\"formErr\" hidden></p>\n      <div class=\"row\">\n        <button class=\"btn\" type=\"submit\" id=\"pdfBtn\">Get the PDF</button>\n        <button class=\"btn ghost\" type=\"button\" id=\"again\">Take it again</button>\n      </div>\n      <p class=\"note\">Only Iryna Voznesenskaya sees your data. It is not shared with third parties.</p>\n    </form>\n    <span class=\"status\" id=\"status\" hidden></span>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n(function fillCountries(){\n  const sel = document.getElementById('fCountry'); if (!sel) return;\n  const g1 = document.createElement('optgroup'); g1.label = 'Frequently chosen';\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = 'All countries';\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option('Other country', OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n})();\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\nconst LS = 'irinaTestsLead';\nfunction loadLead(){ try { return JSON.parse(localStorage.getItem(LS) || 'null'); } catch(e){ return null; } }\nfunction saveLead(v){ try { localStorage.setItem(LS, JSON.stringify(v)); } catch(e){} }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  const saved = loadLead();\n  el('fName').value = saved?.name || LEAD_HOOKS.personName() || '';\n  if (saved){\n    el('fEmail').value = saved.email || ''; el('fContact').value = saved.contact || '';\n    el('fCountry').value = (COUNTRIES.includes(saved.country) || saved.country === OTHER_COUNTRY) ? saved.country : '';\n    el('fCity').value = saved.city || '';\n  }\n  setErr(''); setStatus('');\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(){\n  const stage = el('stage'); stage.innerHTML = '';\n  window.__PDF = true; let blocks; try { blocks = buildBlocks(); } finally { window.__PDF = false; }\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footerLine()}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  const mk = b => { const h = document.createElement('div'); h.innerHTML = b.html; return h.firstElementChild; };\n  const over = () => body.scrollHeight > body.clientHeight + 1;\n  const used = new Set();\n  for (let i = 0; i < blocks.length; i++){\n    const b = blocks[i];\n    if (!b.html || used.has(i)) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const node = mk(b);\n    body.appendChild(node);\n    if (over() && body.children.length > 1){\n      node.remove();\n      // свободное место внизу страницы заполняем небольшими «плавающими» блоками, которые идут дальше (float: true)\n      for (let j = i + 1; j < blocks.length; j++){\n        if (!blocks[j].float || used.has(j) || !blocks[j].html) continue;\n        const f = mk(blocks[j]); body.appendChild(f);\n        if (over()) f.remove(); else used.add(j);\n      }\n      body = newPage(); body.appendChild(node);\n    }\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length === 1){   // один блок выше страницы — уменьшаем, чтобы ничего не обрезалось\n      const k = body.clientHeight / node.scrollHeight;\n      node.style.transformOrigin = 'top left'; node.style.transform = `scale(${k})`; node.style.width = (100 / k) + '%';\n    }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  const bg = getComputedStyle(document.documentElement).getPropertyValue('--pdf-bg').trim() || '#FFFFFF';\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nfunction translit(t){\n  const m = {а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'e',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'sch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya',і:'i',ї:'yi',є:'ye',ґ:'g'};\n  return String(t).toLowerCase().split('').map(c => m[c] ?? c).join('').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');\n}\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\n\nasync function sendLead(lead){\n  if (!ENDPOINT) return;\n  const src = new URLSearchParams(location.search);\n  const sv = surveyAnswers();\n  const t = LEAD_HOOKS.payload();\n  const payload = {\n    ...lead,\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG,\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    result: t.result, scores: t.scores, notes: t.notes || '',\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n  try {\n    await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n  } catch(e){ /* PDF всё равно выдаётся */ }\n}\n\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault(); setErr('');\n  const lead = {\n    name: el('fName').value.trim(), email: el('fEmail').value.trim(), contact: el('fContact').value.trim(),\n    country: el('fCountry').value.trim(), city: el('fCity').value.trim(), marketing: el('fNews').checked\n  };\n  if (!lead.name) return setErr('Please enter your name.');\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return setErr('Please check your e-mail: it looks like there is a mistake.');\n  if (!lead.country) return setErr('Please choose a country from the list.');\n  if (!el('fConsent').checked) return setErr('To get the PDF, please agree to the processing of your data.');\n  if (!window.jspdf || !window.html2canvas) return setErr('The PDF module could not be loaded. Check your internet connection and reload the page.');\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus('Preparing your PDF…');\n  try {\n    saveLead(lead);\n    window.__leadCountry = lead.country;\n    await sendLead(lead);\n    const blob = await buildPdf();\n    const fname = [TEST_META.name, ...LEAD_HOOKS.fileNames(), new Date().toLocaleDateString(DATE_LOCALE)].filter(Boolean).join(' — ').replace(/[\\\\/:*?\"<>|]+/g, ' ').replace(/\\s+/g, ' ').trim();\n    await saveBlob(blob, fname + '.pdf');\n    setStatus('Done! Your PDF has been saved. If it did not open, check your “Downloads” folder.');\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? 'Saving was cancelled.' : 'The PDF could not be prepared. Please try again.');\n  } finally { btn.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
